require_once __DIR__.'/includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT s.*,COALESCE(c.name,'Walk-in customer') customer,c.phone,u.name staff FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE s.id=?");$st->execute([$id]);$sale=$st->fetch();if(!$sale){http_response_code(404);exit('Invoice not found');}$st=$pdo->prepare("SELECT * FROM sale_items WHERE sale_id=?");$st->execute([$id]);$items=$st->fetchAll();layout_start('Invoice '.$sale['invoice_no'],'sales');?>
